def first_item(shelf):
    """Return the item in the first slot (slot 0) of the given shelf."""
    # Optional bounds sanity check; if shelf has no slots, it's empty.
    try:
        if getattr(shelf, "size", None) == 0:
            return None
    except Exception:
        # If shelf.size is not accessible for some reason, ignore.
        pass

    return shelf.get(0)

