import kiln


def on_hand(inv, code) -> int:
    """Return on-hand units of the human-typed product code in inventory.

    Normalizes the typed code by stripping surrounding whitespace and
    canonicalizing via kiln.sku.
    """
    # Quick shape checks
    if not hasattr(inv, "count"):
        raise TypeError("inv must provide a count(code) method")
    if not hasattr(kiln, "sku"):
        raise RuntimeError("kiln must provide sku(text)")

    canonical_code = kiln.sku(code.strip())
    return inv.count(canonical_code)

import datetime


def year_total(ledger, account, year) -> int:
    """Return the total amount posted to `account` during calendar year `year`.

    The Ledger API returns entries using between(start, end) semantics:
    start-inclusive, end-exclusive.
    """
    start = datetime.date(year, 1, 1)
    end = datetime.date(year + 1, 1, 1)
    return sum(
        amount
        for (_date, acct, amount) in ledger.between(start, end)
        if acct == account
    )

