def position_of(shelf, item) -> int:
    """Return the 0-based slot index of `item` on `shelf`, or -1 if absent."""
    slot = shelf.find(item)
    if slot is None:
        return -1

    # Disambiguate: some implementations may use 0 as the miss value.
    try:
        if shelf.get(slot) == item:
            return slot
    except Exception:
        pass
    return -1

