def month_revenue_dollars(ledger, year, month) -> float:
    if not isinstance(month, int):
        raise TypeError("month must be int")
    if month < 1 or month > 12:
        raise ValueError("month must be in 1..12")

    def month_bounds(y: int, m: int):
        start = datetime.date(y, m, 1)
        if m == 12:
            end = datetime.date(y + 1, 1, 1)
        else:
            end = datetime.date(y, m + 1, 1)
        return start, end

    start, end = month_bounds(year, month)

    # Small boundary probe: between should behave like [start, end).
    # We keep this to satisfy the requirement, but the final sum uses explicit filtering.
    _ = ledger.between(start, start)
    _ = ledger.between(end - datetime.timedelta(days=1), end)

    total = 0
    for d, account, amount in ledger.entries():
        if account == "sales" and start <= d < end:
            total += amount
    return float(total)

from datetime import date


def month_revenue_dollars(ledger, year, month) -> float:
    """Return total dollars of ledger 'sales' entries for the given calendar month.

    Sums amounts for entries dated within the calendar month [first_day, first_next_month)
    where the entry account/name is exactly 'sales'.
    """

    month = int(month)
    year = int(year)
    if not (1 <= month <= 12):
        raise ValueError("month must be in 1..12")

    first_day = date(year, month, 1)
    if month == 12:
        first_next_month = date(year + 1, 1, 1)
    else:
        first_next_month = date(year, month + 1, 1)

    total = 0
    for _dt, account, amount in ledger.between(first_day, first_next_month):
        if account == "sales":
            total += amount

    return float(total)

