def has_activity(ledger, day: datetime.date) -> bool:
    """Return True iff ledger has at least one entry dated `day`."""

    # Fast path: some implementations may include entries for between(day, day)
    try:
        if ledger.between(day, day):
            return True
    except Exception:
        pass

    # Correctness fallback: scan all entries and match exact date.
    try:
        for ent in ledger.entries():
            # Defensive shape check: expected (date, account, amount)
            if not isinstance(ent, tuple) or len(ent) != 3:
                continue
            if ent[0] == day:
                return True
    except Exception:
        return False

    return False

import kiln


def top_key(a, b) -> str:
    """Return the key with the largest combined quantity from two (key, qty) lists."""
    merged = kiln.merge(a, b)
    if not merged:
        raise ValueError("Cannot determine top key from empty inputs")

    best_key = None
    best_qty = None

    for key, qty in merged:
        if best_qty is None or qty > best_qty or (qty == best_qty and key < best_key):
            best_qty = qty
            best_key = key

    return best_key
